def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))

    # Find the contiguous non-background, non-marker pattern.
    pattern = None
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg and value != 6:
                start = c
                while start > 0 and row[start - 1] != bg and row[start - 1] != 6:
                    start -= 1
                end = c
                while end + 1 < w and row[end + 1] != bg and row[end + 1] != 6:
                    end += 1
                pattern = row[start:end + 1]
                break
        if pattern is not None:
            break

    if pattern is None:
        return out

    # Copy the pattern at each isolated marker, aligning its middle cell to the marker.
    mid = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                left = c - mid
                for i, value in enumerate(pattern):
                    cc = left + i
                    if 0 <= cc < w:
                        out[r][cc] = value
    return out
